            make_q("What is Group Normalization (Wu & He, 2018)?", ["Dividing channels into G groups and performing normalization within each group along spatial dimensions independently of batch size", "Normalizing groups of users in collaborative filtering", "Normalizing batches into groups of 32", "A method for federated learning"], 0, "Group Norm divides the channel dimension into G groups (e.g. 32) and normalizes within each group, matching BN accuracy while remaining batch-independent."),
            make_q("What is Instance Normalization primarily used for?", ["Image classification on ImageNet", "Style transfer and generative models (GANs) to strip away instance-specific contrast and lighting style", "Tabular regression", "Speech recognition"], 1, "Instance Normalization normalizes each sample and channel independently, discarding contrast/style variations while retaining structural content."),
            make_q("What is Weight Decay in gradient descent optimization?", ["Adding a penalty proportional to the squared magnitude of weights (L2) to the loss function, which causes weights to decay toward zero on each step", "Reducing the number of weights every epoch", "Pruning zero weights", "Decreasing the precision from 32-bit to 16-bit"], 0, "Weight decay penalizes large weights, mathematically equivalent to L2 regularization in standard SGD: theta <- (1 - lr * lambda) * theta - lr * grad."),
