            make_q("How does Spectral Normalization regularize neural networks (Miyato et al., 2018)?", ["By dividing each weight matrix W by its largest singular value (spectral norm) sigma(W), enforcing a Lipschitz constraint <= 1", "By computing FFT of weights", "By normalizing spectra of audio waves", "By setting eigenvalues to zero"], 0, "Spectral Normalization bounds the Lipschitz constant of each layer to 1, stabilizing training in GAN discriminators."),
            make_q("What is the primary danger of over-regularization?", ["The model underfits, failing to capture meaningful underlying patterns in the training data", "The model trains too quickly", "The model achieves 100% test accuracy", "The model runs out of VRAM"], 0, "Excessive regularization overly constrains model capacity, causing severe underfitting and poor performance on both training and test data."),
